import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Phased Implementation Plan","description":"","frontmatter":{"title":"Phased Implementation Plan"},"headers":[],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md","lastUpdated":1793266312000}`),a={name:`guide/roadmap.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_14-phased-implementation-plan" tabindex="-1">14. Phased Implementation Plan <a class="header-anchor" href="#_14-phased-implementation-plan" aria-label="Permalink to “14. Phased Implementation Plan”">​</a></h1><h2 id="p0-core-recovery-engine" tabindex="-1">P0: Core recovery engine <a class="header-anchor" href="#p0-core-recovery-engine" aria-label="Permalink to “P0: Core recovery engine”">​</a></h2><p>Goal: implement a complete, testable recovery loop first, without wiring in complex network capabilities.</p><p>Implementation items:</p><ol><li>Cargo Workspace.</li><li>Domain models such as Resource, Dependency, Evidence, Diagnosis, RecoveryPolicy and RecoveryRun.</li><li>Configuration parsing and validation.</li><li>Dependency graph construction and cycle detection.</li><li>Process Probe.</li><li>Exec Probe.</li><li>Consecutive failure thresholds and health state transitions.</li><li>The RecoveryRun state machine.</li><li>Ordered candidate actions.</li><li>Re-verification after a recovery action executes.</li><li>Re-diagnosis after failure.</li><li>Timeouts, budgets and cooldowns.</li><li>Per-resource recovery mutexes.</li><li>SQLite persistence.</li><li>Crash recovery and unknown-outcome handling.</li><li>Basic CLI commands.</li><li>Structured logging and audit events.</li><li>Integration tests and fault injection.</li></ol><p>P0 does not include:</p><ul><li>HTTP Probe.</li><li>Web Dashboard.</li><li>Remote management API.</li><li>Plugin marketplace.</li><li>OpenClash.</li><li>Complex Wi-Fi recovery.</li><li>Enterprise notification platforms.</li></ul><p>Acceptance criteria:</p><ul><li>A process exiting can be detected.</li><li>A controlled command failing can trigger recovery.</li><li>When the first recovery plan fails, the second plan can be selected.</li><li>When a command returns success but the resource is still unhealthy, recovery must not be reported as successful.</li><li>When a dependency is unhealthy, upstream actions do not execute early.</li><li>The same resource never runs multiple recovery tasks concurrently.</li><li>After Custos crashes and restarts, unfinished tasks can be resumed.</li><li>Actions with unknown outcomes are not unconditionally repeated.</li><li>All state transitions are traceable through logs and the database.</li><li>Every task that exhausts its budget terminates explicitly.</li></ul><h2 id="p1-plugin-runtime-and-notification-infrastructure" tabindex="-1">P1: Plugin runtime and notification infrastructure <a class="header-anchor" href="#p1-plugin-runtime-and-notification-infrastructure" aria-label="Permalink to “P1: Plugin runtime and notification infrastructure”">​</a></h2><p>Implementation items:</p><ol><li>The JSON-RPC 2.0 stdio plugin protocol.</li><li>Plugin capability declarations.</li><li>Plugin start, shutdown and restart management.</li><li>Timeouts, cancellation and output limits.</li><li>Plugin crash isolation.</li><li>NotificationEvent.</li><li>Local log channel.</li><li>Built-in Webhook channel.</li><li>Built-in SMTP channel.</li><li>Persisted notification queue.</li><li>Notification retry, deduplication and dead-letter states.</li><li>CLI notification status and retry commands.</li><li>Plugin permission and capability checks.</li></ol><p>Acceptance criteria:</p><ul><li>A plugin crash does not exit the core process.</li><li>Heavy stderr output does not block protocol communication.</li><li>An unresponsive plugin times out within the configured limit.</li><li>While the network is down, notifications stay in the local queue.</li><li>Once the network recovers, queued notifications continue sending.</li><li>Notification delivery failure does not affect recovery tasks.</li><li>Sensitive fields never reach ordinary logs.</li></ul><h2 id="p2-platform-base-capabilities" tabindex="-1">P2: Platform base capabilities <a class="header-anchor" href="#p2-platform-base-capabilities" aria-label="Permalink to “P2: Platform base capabilities”">​</a></h2><p>Prioritize Linux and Windows.</p><p>Implementation items:</p><ul><li>Process management.</li><li>systemd service control.</li><li>Windows Service control.</li><li>Platform capability detection.</li><li>Platform permission checks.</li><li>System reboot action.</li><li>Basic local network probing.</li><li>Platform adapter integration tests.</li></ul><p>Acceptance criteria:</p><ul><li>On Linux without systemd, capability-unsupported is reported correctly instead of misexecuting.</li><li>Windows service operations have timeouts and result verification.</li><li>High-risk operations without explicit authorization are rejected.</li><li>Platform-specific errors convert into unified fault results.</li></ul><h2 id="p3-network-proxy-and-real-self-healing-scenarios" tabindex="-1">P3: Network, proxy and real self-healing scenarios <a class="header-anchor" href="#p3-network-proxy-and-real-self-healing-scenarios" aria-label="Permalink to “P3: Network, proxy and real self-healing scenarios”">​</a></h2><p>Implementation items:</p><ul><li>Network interface probing.</li><li>Gateway and route probing.</li><li>DNS probing.</li><li>HTTP Probe.</li><li>Proxy connection and authentication diagnosis.</li><li>Mihomo plugin.</li><li>cloudflared plugin.</li><li>Windows Wi-Fi recovery.</li><li>OpenWrt network adapter.</li><li>OpenClash plugin.</li><li>End-to-end verification after network recovery.</li><li>Mutexes and risk control for network operations.</li></ul><p>Acceptance scenarios:</p><ol><li>Sunlogin offline but the network fine: only Sunlogin-related services are recovered.</li><li>Wi-Fi disconnected: restore the network first, then verify remote management capability.</li><li>Proxy healthy, Tunnel abnormal: restart the Tunnel.</li><li>Proxy broken, Tunnel abnormal: recover the proxy first, then handle the Tunnel.</li><li>Proxy returns 407: identify the authentication problem; do not declare the service down.</li><li>Proxy recovered but the Tunnel is still abnormal: diagnose the Tunnel again.</li><li>Every recovery plan failed: stop automatic handling and notify.</li><li>The network drops again during recovery: the local engine keeps running and persists results.</li></ol><h2 id="p4-optional-management-interface-and-extensions" tabindex="-1">P4: Optional management interface and extensions <a class="header-anchor" href="#p4-optional-management-interface-and-extensions" aria-label="Permalink to “P4: Optional management interface and extensions”">​</a></h2><p>Implementation items:</p><ul><li>Web Dashboard, disabled by default.</li><li>Resource list and health status.</li><li>Dependency graph display.</li><li>RecoveryRun timeline.</li><li>Notification status.</li><li>Configuration checks.</li><li>Richer notification plugins.</li><li>macOS adaptation.</li><li>BSD adaptation.</li><li>Full OpenWrt capability.</li><li>Plugin signing and distribution policy.</li><li>A more complete operation authorization interface.</li></ul><p>Acceptance criteria:</p><ul><li>With the Dashboard disabled by default, no port is listened on.</li><li>When the Dashboard is unavailable, core functionality is unaffected.</li><li>The Dashboard never directly executes actions that bypass the Core Engine.</li><li>High-risk operations still go through the unified permission and audit process.</li></ul><hr><h2 id="implementation-tracking" tabindex="-1">Implementation tracking <a class="header-anchor" href="#implementation-tracking" aria-label="Permalink to “Implementation tracking”">​</a></h2><p>Check off each phase with its commit hash once it lands; for sources and acceptance criteria see the corresponding phase above.</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> P0 core recovery engine (commit: __)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> P1 plugin runtime and notification infrastructure (commit: __)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> P2 platform base capabilities (commit: __)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> P3 network, proxy and real self-healing scenarios (commit: __)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> P4 optional management interface and extensions (commit: __)</label></li></ul>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};